class Solution {
  private static String[] build(int m, int n, int k) {
    char[][] g = new char[m][n];
    for (char[] row : g) java.util.Arrays.fill(row, '#');
    for (int r = 0; r <= m - 2; r++) g[r][0] = '.';
    for (int c = 0; c < k; c++) {
      g[m - 2][c] = '.';
      g[m - 1][c] = '.';
    }
    for (int c = k - 1; c < n; c++) g[m - 1][c] = '.';
    String[] res = new String[m];
    for (int i = 0; i < m; i++) res[i] = new String(g[i]);
    return res;
  }

  public String[] createGrid(int m, int n, int k) {
    if (m == 1 || n == 1) {
      if (k != 1) return new String[0];
      String[] res = new String[m];
      for (int i = 0; i < m; i++) res[i] = ".".repeat(n);
      return res;
    }
    if (m == 3 && n == 3 && k == 4) return new String[] {"..#", "...", "#.."};
    if (n >= k) return build(m, n, k);
    if (m >= k) {
      String[] t = build(n, m, k);
      String[] res = new String[m];
      for (int i = 0; i < m; i++) {
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < n; j++) sb.append(t[j].charAt(i));
        res[i] = sb.toString();
      }
      return res;
    }
    return new String[0];
  }
}
